  const GATED_CARD = /\{!isPublicMode && !!userProfile\?\.person_id && !!silvisFakId && userProfile\.person_id === silvisFakId && myId === silvisFakId && \(\s*<CallTotalsCard\b[^]*?\/>\s*\)\}/g;
