  const r120 = rq(11, "s5", "2026-10-30", "2027-02-26"), r121 = rq(12, "s5", "2026-10-30", "2027-02-27");
  const r2126 = rq(13, "s5", "2026-11-03", "2126-11-05"), r20261 = rq(14, "s5", "2026-11-04", "20261-11-04"), rJunk = rq(15, "s5", "2026-11-04", "not-a-date");
