      const weeks = { [K[0]]: W("s1", "s2", "s3", "s4", "s5", "s2"), [K[1]]: W("s6", "s1", "s7", "s7", "s2", "s7"), [K[2]]: W("s3", "s4", "s5", "s1", "s2", "s4") };
      const r = run8(weeks, K.map(G.parse), hol);
