          const k = ["mon", "tue", "wed", "thu"][G.parse(n).getDay() - 1], wi = K.findIndex(mm => mm <= n && n < G.fmt(G.addD(G.parse(mm), 7)));
          if (!k || wi < 0) return;
          const w2 = JSON.parse(JSON.stringify(weeks)); w2[K[wi]].nights[k] = "s6";
          const r2 = run8(w2, mons, hol);
