      const weeks = { [K[0]]: W("s1", "s2", "s3", "s4", "s5", "s7"), [K[1]]: W("s6", "s6", "s6", "s6", "s4", "s6"), [K[2]]: W("s7", "s5", "s1", "s2", "s3", "s4") };
